CREATE view kalas as SELECT   dbo.kalas_sub.NUMBER, dbo.TAGCOD.BARGAH, dbo.TCOD_ANBAR.NAMES AS ANBNAME, dbo.kalas_sub.NUMBER1, dbo.kalas_sub.DATE_N, dbo.kalas_sub.N_S, dbo.CUST_HESAB.NAME AS CUSTNAME, dbo.kalas_sub.MOLAH, dbo.kalas_sub.ANBARF, dbo.kalas_sub.FNUMCO,  dbo.kalas_sub.MEGH, dbo.kalas_sub.MEGHk, dbo.kalas_sub.MEGH_MAR, dbo.kalas_sub.MABL, dbo.STUF_DEF.NAME AS kala, dbo.kalas_sub.MABL_K,dbo.kalas_sub.SANAD_NO, dbo.kalas_sub.CUST_NO, dbo.TCOD_VAHEDS.NAMES AS VAHEDNAME, dbo.TCOD_STUFGROUP.NAMES AS GRPNAME,CAST(dbo.STUF_DEF.CODE AS BIGINT) AS code, dbo.kalas_sub.hes, dbo.kalas_sub.USER_NAME, dbo.SHIFT.SHNAME, dbo.CUSTKIND.CUSTKNAME, dbo.DEPART.DEPNAME, dbo.kalas_sub.MANDAH, dbo.SHIFT.SHIFT_ID, dbo.DEPART.DEPATMAN, dbo.CUSTKIND.CUST_COD,dbo.TAGCOD.CODE AS TAGCODE, dbo.TCOD_STUFGROUP.CODE AS GRPCODE, dbo.TCOD_ANBAR.CODE AS ANBARCODE, dbo.TCOD_VAHEDS.CODE AS VAHCODE, dbo.kalas_sub.id, dbo.kalas_sub.MAS, dbo.kalas_sub.N_RASID, dbo.STUF_DEF.N_FANI, dbo.kalas_sub.SHARAYET, dbo.kalas_sub.IMBAA, dbo.kalas_sub.HMBAA, dbo.kalas_sub.TAMIR, dbo.kalas_sub.TICMBAA, dbo.kalas_sub.OKF, dbo.STUF_DEF.TOZIH,  dbo.STUF_DEF.B_SEF, dbo.STUF_DEF.N_SEF, dbo.STUF_DEF.MIN_M, dbo.STUF_DEF.MAX_M, dbo.STUF_DEF.RADAH, dbo.STUF_DEF.KINDK, dbo.STUF_DEF.MABL_F, dbo.STUF_DEF.DEPART, dbo.STUF_DEF.CMBAA, dbo.STUF_DEF.VAZN * dbo.kalas_sub.MEGHk AS vazn, dbo.kalas_sub.N_TAF, dbo.kalas_sub.TOTALARZ, dbo.kalas_sub.N_KOL, dbo.kalas_sub.N_MOIN, dbo.kalas_sub.MM, dbo.kalas_sub.KHFR, dbo.kalas_sub.GHFR,  dbo.kalas_sub.TAG, dbo.STUF_DEF.VAHED, dbo.kalas_sub.SADER, dbo.kalas_sub.ARZD, dbo.kalas_sub.ARZKIND, dbo.kalas_sub.CDDATE, dbo.kalas_sub.CDTIME, dbo.kalas_sub.OKDATE, dbo.kalas_sub.OKTIME, dbo.kalas_sub.AVRAGE, dbo.kalas_sub.mabrial, dbo.kalas_sub.ANBARAS,  dbo.CUST_HESAB.ECODE, dbo.CUST_HESAB.PCODE, dbo.CUST_HESAB.IYALAT, dbo.CUST_HESAB.CITY, dbo.kalas_sub.TKHN, dbo.stuf_def_nfani.col1,dbo.stuf_def_nfani.col2, dbo.stuf_def_nfani.col3, dbo.stuf_def_nfani.col4, dbo.stuf_def_nfani.col5, dbo.stuf_def_nfani.col6, dbo.stuf_def_nfani.col7, dbo.stuf_def_nfani.col8, dbo.stuf_def_nfani.col9, dbo.stuf_def_nfani.coln1, dbo.stuf_def_nfani.coln2, dbo.stuf_def_nfani.coln3, dbo.stuf_def_nfani.coln4, dbo.stuf_def_nfani.coln5, dbo.stuf_def_nfani.coln6, dbo.stuf_def_nfani.coln7, dbo.stuf_def_nfani.coln8, dbo.stuf_def_nfani.coln9, dbo.CUST_HESAB.ADDRESS, dbo.CUST_HESAB.TEL, dbo.CUST_HESAB.CODE_E, dbo.CUST_HESAB.MCODEM, dbo.CUST_HESAB.MOBILE, dbo.CUST_HESAB.Longitude, dbo.CUST_HESAB.Latitude, dbo.CUST_HESAB.ROUTE_NAME, dbo.CUST_HESAB.OSTANID, dbo.CUST_HESAB.SHAHRID, dbo.TCOD_OSTAN.OSNAME , dbo.TCOD_CITY.CITYNAME FROM            dbo.TCOD_STUFGROUP RIGHT OUTER JOIN  dbo.TCOD_OSTAN RIGHT OUTER JOIN  dbo.CUST_HESAB ON dbo.TCOD_OSTAN.OSCODE = dbo.CUST_HESAB.OSTANID LEFT OUTER JOIN   dbo.TCOD_CITY ON dbo.CUST_HESAB.SHAHRID = dbo.TCOD_CITY.CITYCODE RIGHT OUTER JOIN dbo.TCOD_ANBAR RIGHT OUTER JOIN dbo.kalas_sub INNER JOIN dbo.TAGCOD ON dbo.kalas_sub.TAG = dbo.TAGCOD.CODE INNER JOIN dbo.STUF_DEF ON dbo.kalas_sub.CODE = dbo.STUF_DEF.CODE ON dbo.TCOD_ANBAR.CODE = dbo.kalas_sub.ANBAR LEFT OUTER JOIN dbo.TCOD_VAHEDS ON dbo.kalas_sub.VAHED_K = dbo.TCOD_VAHEDS.CODE LEFT OUTER JOIN dbo.stuf_def_nfani ON dbo.STUF_DEF.CODE = dbo.stuf_def_nfani.CODE LEFT OUTER JOIN dbo.CUSTKIND ON dbo.kalas_sub.CUST_KIND = dbo.CUSTKIND.CUST_COD LEFT OUTER JOIN dbo.SHIFT ON dbo.kalas_sub.SHIFT = dbo.SHIFT.SHIFT_ID LEFT OUTER JOIN  dbo.DEPART ON dbo.kalas_sub.DEPATMAN = dbo.DEPART.DEPATMAN ON dbo.CUST_HESAB.hes = dbo.kalas_sub.hes ON dbo.TCOD_STUFGROUP.CODE = dbo.STUF_DEF.RADAH
